        Current = Mathf.Max(0, Current - amount);
        Changed?.Invoke(Current, stats != null ? stats.maxHealth : 100);
        if (Current == 0)
        {
            Died?.Invoke();
            Destroy(gameObject, 2f);
        }
    }
}
